# 指标 单元探测 —— 直接粘贴到新算子库 pythonInput 节点
# 逻辑：① EngagementCycle 映射内连接 ② 过滤探测状态 ③ 按 (Time,平台,目标,传感器) 分组，距离取 mean
import pandas as pd
import numpy as np

def T(name):
    return input_df_dict.get(name, input_df_dict.get(name + ".csv", pd.DataFrame()))

def C(df, name, default=None):
    return df[name] if name in df.columns else pd.Series(default, index=df.index, dtype=object)

def pick(df, *names, default="未知"):
    # 按优先级取第一个存在的列，兼容原始导出表与增强表
    for n in names:
        if n in df.columns:
            return df[n].fillna(default).astype(str)
    return pd.Series(default, index=df.index, dtype=object)

DET_STATUS = {"KnownDomain", "KnownType", "KnownClass", "PreciseID"}
det = T("DetectionIdentificationChanged")
eng = T("EngagementCycle")
units = T("UnitCreated")
COLS = ["探测平台", "探测目标", "首次发现距离", "探测传感器"]

# ① ContactID -> ContactActualUnitID 去重映射，默认内连接；再补目标名称
if det.empty or "ContactID" not in det.columns:
    output_df = pd.DataFrame(columns=COLS)
else:
    df = det.copy()
    if "ContactActualUnitID" not in df.columns and not eng.empty and {"ContactID", "ContactActualUnitID"}.issubset(eng.columns):
        cmap = eng[["ContactID", "ContactActualUnitID"]].dropna().drop_duplicates("ContactID")
        df = df.merge(cmap, on="ContactID", how="inner")
    if "Time" in df.columns:
        df["Time"] = pd.to_datetime(df["Time"], errors="coerce")

    # ② 探测状态过滤：Unknown 等其它状态排除；缺列时不额外过滤
    keep = C(df, "IdentificationStatus").astype(str).isin(DET_STATUS) if "IdentificationStatus" in df.columns else pd.Series(True, index=df.index)
    df = df.loc[keep].copy()
    if df.empty:
        output_df = pd.DataFrame(columns=COLS)
    else:
        # 名称/传感器/距离：优先用增强列，缺列时回退到原始导出列
        unit_names = units.drop_duplicates("UnitID").set_index("UnitID")["UnitName"] if not units.empty and {"UnitID", "UnitName"}.issubset(units.columns) else pd.Series(dtype=object)
        target_name = pick(df, "ContactActualName", "ContactName", default="未知目标")
        if "ContactActualName" not in df.columns and "ContactActualUnitID" in df.columns and len(unit_names):
            mapped = df["ContactActualUnitID"].map(unit_names)
            target_name = mapped.fillna(target_name).astype(str)
        df["_p"] = pick(df, "SensorPlatformName", "SensorPlatformID", default="未知平台")
        df["_t"] = target_name
        df["_s"] = pick(df, "SensorName", default="未知传感器")
