def _is_weapon(v):
    return not pd.isna(v) and str(v).strip().lower() in ('武器', 'weapon', 'weapons', 'missile', 'munitions')

def _norm(v):
    if pd.isna(v): return ''
    s = str(v).strip().lower()
    return 'red' if s in ('红方', 'red') else ('blue' if s in ('蓝方', 'blue') else s)

if not endgame.empty and 'EndgameMessage' in endgame.columns:
    endgame = endgame[~endgame['EndgameMessage'].fillna('').astype(str).str.lower().str.contains('no point defence systems employed', na=False)].copy()
if not endgame.empty and 'WeaponID' in endgame.columns:
    rk = {'KILL': 5, 'HIT': 4, 'POINTDEF:SUCCESS': 3, 'MISS': 2}
    endgame['_rk'] = C(endgame, 'Result', '').astype(str).str.upper().map(rk).fillna(0)
    endgame = endgame.sort_values('_rk', ascending=False).drop_duplicates('WeaponID', keep='first')

u_side, u_type = {}, {}
if not units.empty and 'UnitID' in units.columns:
    ud = units.dropna(subset=['UnitID']).drop_duplicates('UnitID')
    sc = 'UnitSide' if 'UnitSide' in ud.columns else ('Side' if 'Side' in ud.columns else None)
    if sc: u_side = dict(zip(ud['UnitID'].astype(str), ud[sc].fillna('').astype(str)))
    if 'UnitType' in ud.columns: u_type = dict(zip(ud['UnitID'].astype(str), ud['UnitType']))

sides, seen = [], set()
for src in ([sides_df['SideName'].dropna().tolist()] if not sides_df.empty and 'SideName' in sides_df.columns else []) + [list(u_side.values())]:
    for v in src:
        s = str(v).strip()
        ns = _norm(s)
        if ns and ns not in seen:
            seen.add(ns); sides.append((ns, s))

frat = {ns: 0 for ns, _ in sides}
hits = {ns: 0 for ns, _ in sides}
if not endgame.empty:
    for _, r in endgame.iterrows():
        res = str(r['Result']).strip().upper() if 'Result' in endgame.columns and pd.notna(r['Result']) else ''
        if res not in ('HIT', 'KILL'): continue
        fs = str(r['WeaponSide']).strip() if 'WeaponSide' in endgame.columns and pd.notna(r['WeaponSide']) else ''
        fn = _norm(fs)
        if not fn: continue
        if fn not in hits:
            sides.append((fn, fs)); frat[fn] = 0; hits[fn] = 0
        hits[fn] += 1
        tid = str(r['TargetID']) if 'TargetID' in endgame.columns and pd.notna(r['TargetID']) else ''
        if not tid or (tid in u_type and _is_weapon(u_type[tid])): continue
        ts = str(r['TargetSide']).strip() if 'TargetSide' in endgame.columns and pd.notna(r['TargetSide']) else u_side.get(tid, '')
        if _norm(ts) == fn: frat[fn] += 1

